    local r = h:GetAttribute("Rarity")
    if Opt and Opt.f_rar and type(Opt.f_rar.Value) == "table" and next(Opt.f_rar.Value) and not Opt.f_rar.Value[r] then return false end
    return true
end
function F.quickLine(x)
    local g = F.geo()
    local half = (D.Wo.LineHalfWidth or 182) - 4
    return Vector3.new(math.clamp(x, g.OriginX - half, g.OriginX + half), 4.8, F.lineZ() + 2)
end
F.losParams = RaycastParams.new()
F.losParams.FilterType = Enum.RaycastFilterType.Exclude
function F.clearShot(h)
    local ex = { F.petsFolder() }
    for _, p in ipairs(Players:GetPlayers()) do if p.Character then ex[#ex + 1] = p.Character end end
    local hubs = D.Wo.hubs and select(2, pcall(D.Wo.hubs))
    if type(hubs) ~= "table" then hubs = { Workspace:FindFirstChild("Hub") } end
    for _, hb in pairs(hubs) do local sl = typeof(hb) == "Instance" and hb:FindFirstChild("StartLine") if sl then ex[#ex + 1] = sl end end
    if D.Wo.shotIgnore then local ok, list = pcall(D.Wo.shotIgnore) if ok and type(list) == "table" then for _, v in ipairs(list) do ex[#ex + 1] = v end end end
    F.losParams.FilterDescendantsInstances = ex
    local o = F.quickLine(h.Position.X)
    local hit = Workspace:Raycast(o, h.Position - o, F.losParams)
    return hit == nil or (hit.Position - h.Position).Magnitude < 4
end
function F.score(h, view)
    local d = (h.Position - F.quickLine(h.Position.X)).Magnitude
    if d > view - 8 then return nil end
    local mode = val("f_target", "Best Income")
    if mode == "Nearest" then return -d end
    local inc = tonumber(h:GetAttribute("Income")) or 0
    local p = 1 - math.clamp(d / math.max(view, 1), 0, 1) * 0.5
    if h:GetAttribute("Moving") then p = p * 0.75 end
    if h:GetAttribute("Hide") == "Fly" then p = p * 0.7 end
    if h:GetAttribute("Camo") then p = p * 0.5 end
    local need = tonumber(h:GetAttribute("DartsNeeded")) or 1
    return inc * p / math.max(need - (h:GetAttribute("DartsHit") or 0), 1) - d * 1e-6
end
function F.pickTarget()
    local pets = F.petsFolder()
    if not pets then return nil end
    local world = M.world()
    local wid = F.bestWeapon()
    if not wid then return nil end
    local view = F.view(wid)
    local gz = F.gateZ()
    F.myTier = (F.weaponDef(wid) or {}).Tier or 1
    local list = {}
    for _, m in ipairs(pets:GetChildren()) do
        local h = m:FindFirstChild("Hitbox")
        if h and F.eligible(h, world, gz) then
            local s = F.score(h, view)
            if s then list[#list + 1] = { h = h, s = s } end
        end
    end
    table.sort(list, function(a, b) return a.s > b.s end)
    for i = 1, math.min(#list, 15) do
        if F.clearShot(list[i].h) then return list[i].h, wid end
        F.bad[list[i].h] = os.clock() + 6
    end
    return nil, wid
end
function F.waitAttr(k, want, secs)
    local t0 = os.clock()
    while os.clock() - t0 < secs do
        local v = lp:GetAttribute(k)
        if want == "nil" then if v == nil then return true end
        elseif want == "set" then if v ~= nil then return true end
        elseif v == want then return true end
        task.wait()
    end
    return false
end
function F.ensureEquip(wid, did)
    local changed = false
    local w = M.get("weapons")
    if w and w.equipped ~= wid then M.fire("Equip", "Weapon", wid) changed = true task.wait(0.3) end
    local d = M.get("darts")
    if did and d and d.selected ~= did then M.fire("Equip", "Dart", did) changed = true task.wait(0.3) end
    if changed and lp:GetAttribute("Aiming") then M.fire("ExitAim") F.waitAttr("Aiming", false, 1) end
end
function F.velocity(h)
    local p0, t0 = h.Position, os.clock()
    task.wait(0.1)
    local dt = os.clock() - t0
    if not h.Parent or dt <= 0 then return Vector3.zero end
    local v = (h.Position - p0) / dt
    if v.Magnitude > 80 then return Vector3.zero end
    return v
end
function F.shootAt(h, wid, did)
    local hd = lp.Character and lp.Character:FindFirstChild("Head")
    if not hd then return nil end
    local vel = h:GetAttribute("Moving") and F.velocity(h) or Vector3.zero
    local origin = hd.Position + Vector3.new(0, 0.4, 0)
    local aim = h.Position
    local spd = D.T.DART_SPEED or 300
    for _ = 1, 3 do
        local t = math.clamp((aim - origin).Magnitude / spd, D.T.DART_MIN_TIME or 0.15, D.T.DART_MAX_TIME or 1.2)
        aim = h.Position + vel * t
    end
    F.lastResult = nil
    F.waitPet = h:GetAttribute("PetId")
    M.fire("Fire", wid, did, (aim - origin).Unit)
    S.shots += 1
    local t0 = os.clock()
    local hit0 = h:GetAttribute("DartsHit") or 0
    local function hitUp() return (h:GetAttribute("DartsHit") or 0) > hit0 end
    while not F.lastResult and os.clock() - t0 < 4 and h.Parent and h:GetAttribute("State") == "Awake" and not hitUp() do task.wait() end
    if not F.lastResult then
        if h:GetAttribute("State") ~= "Awake" then F.lastResult = { result = "Sleep" }
        elseif hitUp() then F.lastResult = { result = "Partial" }
        else F.lastResult = { result = "Miss", silent = true } end
    end
    local t1 = os.clock()
    while h.Parent and os.clock() - t1 < 3 do
        local st = h:GetAttribute("State")
        if st == "Asleep" or st == "Awake" then break end
        task.wait()
    end
    local r = F.lastResult
    if r and h:GetAttribute("State") == "Asleep" then r.result = "Sleep" end
    F.waitPet = nil
    return r
end
function F.pause()
    return on("f_pause")
end
function F.holdLine(x)
    local p = F.linePoint(x)
    local r = M.root()
    if r and (r.Position - p).Magnitude > 3 then M.tp(p) task.wait(0.15) end
    return p
end
function F.aimFrom(x)
    local p = F.linePoint(x)
    local r = M.root()
    local need = not r or (r.Position - p).Magnitude > 3
    if need then
        if lp:GetAttribute("Aiming") then M.fire("ExitAim") F.waitAttr("Aiming", false, 1) end
        M.tp(p)
        task.wait(0.2)
    end
    if not lp:GetAttribute("Aiming") then
        M.fire("EnterAim")
        F.waitAttr("Aiming", true, 1.5)
        task.wait(0.5)
    end
end
function F.treadSpot()
    local base = M.myBase()
    local tm = base and base:FindFirstChild("Treadmill")
    local fb = tm and (tm:FindFirstChild("Frame_Base", true) or tm.PrimaryPart)
    return fb and (fb.Position + Vector3.new(0, 3.5, 1)) or nil
end
function F.train(secs)
    local p = F.treadSpot()
    if not p or secs <= 0 then return end
    M.tp(p)
    local t0 = os.clock()
    while RUNNING and os.clock() - t0 < secs and not F.pause() do
        local r = M.root()
        if r and (r.Position - p).Magnitude > 4 then M.tp(p) end
        task.wait(0.1)
    end
end
function F.penSpot()
    local base = M.myBase()
    local fl = base and base:FindFirstChild("Floor")
    if not fl or not fl:IsA("BasePart") then return nil end
    local lineP = F.linePoint(fl.Position.X)
    local loc = fl.CFrame:PointToObjectSpace(lineP)
    local hx, hz = math.max(fl.Size.X / 2 - 4, 0.5), math.max(fl.Size.Z / 2 - 4, 0.5)
    local lx = math.clamp(loc.X + (math.random() * 16 - 8), -hx, hx)
    local lz = math.clamp(loc.Z, -hz, hz) + (loc.Z < 0 and math.random() * 6 or -math.random() * 6)
    lz = math.clamp(lz, -hz, hz)
    return fl.CFrame:PointToWorldSpace(Vector3.new(lx, fl.Size.Y / 2, lz))
end
function F.place()
    local spot = F.penSpot()
    if not spot then return false, "no pen" end
    if F.pickPos and F.pickT then
        local spd = math.max(tonumber(M.attr("BaseSpeed", 16)) or 16, 8)
        if M.world() == "Abyss" then spd = spd * (1 - (1 - math.clamp(tonumber(M.attr("WaterRelief", 0)) or 0, 0, 1)) * (D.Wo.AbyssSpeedFactor or 0.5)) end
        local need = (F.pickPos - spot).Magnitude / (2 * math.max(spd, 4)) - (os.clock() - F.pickT) - 0.35
        if need > 0.5 then
            if on("f_train") then S.task = __T["Training while it settles"] F.train(need)
            else
                S.task = __T["Waiting to place"]
                M.tp(spot + Vector3.new(0, 3, 0))
                local tw = os.clock()
                while RUNNING and os.clock() - tw < need and not F.pause() do task.wait(0.1) end
            end
        end
    end
    if F.pause() then return false, "paused" end
    M.tp(spot + Vector3.new(0, 3, 0))
    task.wait(0.3)
    local t0 = os.clock()
    local gap = F.pickT and 0.6 or 2.5
    F.deposited = nil
    while RUNNING and os.clock() - t0 < 30 and lp:GetAttribute("Carrying") and not F.pause() do
        F.notifyErr.text = ""
        M.fire("PlacePet", spot)
        if F.waitAttr("Carrying", "nil", gap) then
            local tc = os.clock()
            while not F.deposited and os.clock() - tc < 1 do task.wait() end
            local ok = F.deposited ~= nil or not lp:GetAttribute("Eaten")
            LOG("placed after", string.format("%.1f", os.clock() - (F.pickT or t0)), F.deposited and "deposit" or "no deposit event")
            F.pickPos, F.pickT = nil, nil
            return ok, ok and "" or "lost"
        end
        local et = F.notifyErr.text:lower()
        if et:find("plein") or et:find("full") then
            if on("e_sell") then
                LOG("zoo full, selling storage")
                M.call("SellAllStorage")
                task.wait(0.5)
            else
                F.fullUntil = os.clock() + 60
                notify(__T["Zoo full: turn on Auto Sell Storage or expand your zoo"])
                M.fire("SkipPet")
                F.pickPos, F.pickT = nil, nil
                return false, "zoo full"
            end
        end
    end
    return lp:GetAttribute("Carrying") == nil and F.deposited ~= nil, F.notifyErr.text
end
function F.activePet()
    local ap = lp:GetAttribute("ActivePet")
    if not ap then return nil end
    local pets = F.petsFolder()
    for _, m in ipairs(pets and pets:GetChildren() or {}) do
        local h = m:FindFirstChild("Hitbox")
        if h and h:GetAttribute("PetId") == ap then return h end
    end
end
function F.capture()
    local ah = F.activePet()
    if ah and ah:GetAttribute("State") == "Asleep" and ah:GetAttribute("Owner") == lp.UserId then LOG("picking up active", ah:GetAttribute("Species")) return F.carry(ah) end
    local h, wid = F.pickTarget()
    if not h then S.task = "Waiting for pets" return false end
    local did = F.pickDart(h)
    if not did then S.task = __T["Out of darts"] F.bad[h] = os.clock() + 10 return false end
    local sp = h:GetAttribute("Species") or "?"
    local rar = h:GetAttribute("Rarity") or "?"
    S.task = __T["Hunting "] .. rar .. " " .. sp
    F.huntT = os.clock()
    local ax = h.Position.X
    F.aimFrom(ax)
    local tries = 0
    F.misses = 0
    local rejects = 0
    while RUNNING and on("f_auto") and not F.pause() and not S.switching and h.Parent and h:GetAttribute("State") ~= "Asleep" and tries < 12 and rejects < 8 do
        tries += 1
        while lp:GetAttribute("Eaten") and RUNNING do task.wait(0.2) end
        local cd = (S.cdUntil or 0) - Workspace:GetServerTimeNow()
        if cd > 0 then task.wait(math.min(cd, 3.2)) end
        if h:GetAttribute("Owner") ~= 0 and h:GetAttribute("Owner") ~= lp.UserId then break end
        if math.abs(h.Position.X - ax) > 60 then ax = h.Position.X end
        did = F.pickDart(h)
        if not did then break end
        if D.Dt.get(did) and D.Dt.get(did).Mutation then
            F.aimFrom(ax)
            if not F.petClear(h) then did = F.pickDart(h, true) if not did then break end end
        end
        F.ensureEquip(wid, did)
        F.aimFrom(ax)
        local r = F.shootAt(h, wid, did)
        if D.Dt.get and D.Dt.get(did) and D.Dt.get(did).Mutation then LOG("mutation dart", did, "on", rar, sp, "->", tostring(r and r.result), tostring(h:GetAttribute("Mutation"))) end
        local ap = lp:GetAttribute("ActivePet")
        if ap and ap ~= h:GetAttribute("PetId") then local ah2 = F.activePet() if ah2 then LOG("dart hit another pet", ah2:GetAttribute("Species")) return F.carry(ah2) end end
        if not r then r = { result = "Miss", silent = true } end
        if r.cooldownUntil and r.cooldownUntil > 0 then S.cdUntil = r.cooldownUntil end
        if r.result == "Rejected" then
            tries -= 1
            rejects += 1
            if tostring(r.reason):lower():find("recharg") then
                task.wait(0.7)
            else
                LOG("rejected", r.reason)
                M.fire("ExitAim")
                F.waitAttr("Aiming", false, 1)
                task.wait(0.3)
            end
        elseif r.result == "Miss" or r.result == "Dodged" then
            S.misses += 1
            if r.silent then S.cdUntil = Workspace:GetServerTimeNow() + math.max((D.T.MISS_COOLDOWN or 3) - 4, 0.2) end
            F.misses = (F.misses or 0) + 1
            if F.misses >= 2 then F.bad[h] = os.clock() + 25 F.misses = 0 break end
        elseif h:GetAttribute("State") ~= "Asleep" then
            task.wait(D.T.MIN_SHOT_INTERVAL or 0.3)
        end
    end
    if h:GetAttribute("State") ~= "Asleep" or h:GetAttribute("Owner") ~= lp.UserId then
        if h.Parent and h:GetAttribute("State") == "Awake" and (tries >= 12 or rejects >= 8) then F.bad[h] = os.clock() + 20 end
        return false
    end
    LOG("asleep", rar, sp, "shots", tries, string.format("%.1fs", os.clock() - F.huntT))
    return F.carry(h)
end
function F.carry(h)
    local ok, res = pcall(F.carryInner, h)
    S.busy = false
    if not ok then LOG("carry err", res) return false end
    return res
end
function F.carryInner(h)
    S.busy = true
    local id = h:GetAttribute("PetId")
    local sp = h:GetAttribute("Species") or "?"
    local rar = h:GetAttribute("Rarity") or "?"
    local mut = h:GetAttribute("Mutation") or "Normal"
    S.task = __T["Bringing back "] .. rar .. " " .. sp
    local ok = false
    for i = 1, 3 do
        if not h.Parent then break end
        M.tp(h.Position + Vector3.new(0, 2, i == 1 and 2 or 0))
        if F.waitAttr("Carrying", id, 1) then ok = true F.pickPos = h.Position F.pickT = os.clock() break end
    end
    if not ok then
        F.bad[h] = os.clock() + 30
        if lp:GetAttribute("ActivePet") == id then M.fire("SkipPet") end
        M.tp(F.linePoint(h.Position.X))
        LOG("grab failed", sp, F.notifyErr.text)
        return false
    end
    local back = F.linePoint(h.Position.X, F.lineDepth() + 1)
    M.tp(back)
    if not F.waitAttr("CarrySecured", true, 1.5) then
        M.tp(F.linePoint(back.X, F.lineDepth() + 3))
        if not F.waitAttr("CarrySecured", true, 1.5) then
            M.tp(F.linePoint(back.X, F.lineDepth() + 6))
            F.waitAttr("CarrySecured", true, 2)
        end
    end
    S.task = __T["Placing "] .. rar .. " " .. sp
    local placed, why = F.place()
    S.busy = false
    if placed then
        S.caught += 1
        S.lastCatch = (mut ~= "Normal" and (mut .. " ") or "") .. rar .. " " .. sp
        LOG("caught", S.lastCatch)
        if F.rank(rar) >= F.rank("Legendary") or F.mutRank(mut) >= F.mutRank("Gold") then notify(__T["Caught "] .. S.lastCatch .. "!") end
        F.equipT = 0
        return true
    end
    LOG("place failed", why)
    return false
end
task.spawn(function()
