local E = {}
E.cool = {}
function E.ready(k, secs) local t = E.cool[k] if t and os.clock() < t then return false end E.cool[k] = os.clock() + secs return true end
function E.nextWeapon()
    local world = M.world()
    local ord = D.W.orderFor and D.W.orderFor((world ~= "Normal" and world ~= "Halloween") and world or nil) or D.W.Order or {}
    for _, id in ipairs(ord) do
        local w = F.weaponDef(id)
        if w and not M.ownsWeapon(id) and not w.Exclusive and (w.Price or 0) > 0 then return id, w end
    end
end
function E.treadPrice()
