    if world == "Prehistoric" then lv = math.max(tonumber(M.get("treadmillPre")) or 0, 1)
    elseif world == "Abyss" then lv = math.max(tonumber(M.get("treadmillAbyss")) or 0, 1)
    else lv = tonumber(M.get("treadmillLevel")) or 0 end
    local list = (world == "Prehistoric" and D.Tr.Prehistoric) or (world == "Abyss" and D.Tr.Abyss) or D.Tr.Levels or {}
    local nx = list[lv + 1]
